css:
:root { --cu:#a7c503; --bg:#f5f5f5; --ink:#141414; --sub:#7e7e7e; --line:#dcdcdc; --purple:#7d4be5; }
*{box-sizing:border-box} body{margin:0;background:#eee;font-family:Inter,'Noto Sans KR',sans-serif;color:var(--ink)}
.app{width:402px;min-height:100vh;margin:0 auto;background:#fff;border-radius:30px;overflow:hidden;position:relative}
.status-wrap{position:sticky;top:0;z-index:30;background:#fff}
.status-bar{height:37px;display:flex;align-items:center;justify-content:center;font-weight:600}
.top-nav{height:42px;padding:0 21px;display:flex;align-items:center;justify-content:space-between;border-bottom:1px solid #f0f0f0}
.top-nav h1{margin:0;font-size:17px;font-weight:600}
main{padding-bottom:108px;background:var(--bg)}
.screen{display:none;padding:12px 20px 24px}
.screen.active{display:block}
.hero{background:linear-gradient(160deg,#f6f3e7,#f0ebd6);border-radius:16px;padding:18px;margin-top:8px}
.hero h2{font-size:32px;line-height:1.05;margin:0 0 8px}
.hero button{height:42px;border:0;background:var(--cu);color:#fff;border-radius:24px;padding:0 16px;font-weight:700;cursor:pointer}
.quick-menu,.service-grid{display:grid;gap:8px}.quick-menu{grid-template-columns:repeat(5,1fr);margin-top:12px}.service-grid{grid-template-columns:repeat(5,1fr)}
.quick-menu button,.service-grid button{height:44px;border:1px solid var(--line);background:#fff;border-radius:12px;font-size:11px}
.report-card,.service-panel,.receipt{background:#fff;border:1px solid #ebedf5;border-radius:16px;padding:14px;margin-top:12px}
.report-grid{display:grid;gap:8px}.product-list,.event-products{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:10px}
.product{background:#fff;border-radius:12px;padding:10px;border:1px solid #efefef}
.bottom-tab{position:absolute;left:0;right:0;bottom:0;height:92px;display:grid;grid-template-columns:repeat(5,1fr);background:#fff;border-top:1px solid #e6e6e6}
.bottom-tab button{border:0;background:transparent;font-size:11px;cursor:pointer}
#modal-layer{position:fixed;inset:0;display:none;place-items:center;background:rgba(0,0,0,.35);z-index:99}
#modal-layer.open{display:grid}
.popup{display:none;width:min(380px,92vw);background:#d7e687;border:2.5px solid #5ed4bc;border-radius:26px;padding:24px;font-size:20px;font-weight:700;text-align:center}
.popup.open{display:block}
.buy-btn{width:100%;height:59px;border:0;border-radius:30px;background:var(--cu);color:#fff;font-size:24px;cursor:pointer;margin-top:14px}
.coupon-tabs{display:flex;flex-wrap:wrap;gap:6px}.coupon-tabs button{height:32px;border:0;border-radius:16px;padding:0 12px;background:#f6f6f6;color:#878787}.coupon-tabs .on{background:#40d673;color:#fff}
